package com.alex.guestvm;
import android.app.Activity; import android.content.Intent; import android.net.Uri; import android.os.Bundle; import android.view.*; import android.widget.*; import java.io.*;
public class MainActivity extends Activity implements SurfaceHolder.Callback {
 private static final int PICK_ZIP=1002; private static final int PICK_ENGINE=1003; private TextView status,log; private ScrollView logScroll; private SurfaceView surface; private Button startButton,filesButton; private boolean ready; private volatile boolean guestBusy;
 @Override protected void onCreate(Bundle b){super.onCreate(b); getWindow().addFlags(android.view.WindowManager.LayoutParams.FLAG_KEEP_SCREEN_ON);AppLog.init(this);Thread.setDefaultUncaughtExceptionHandler(new Thread.UncaughtExceptionHandler(){public void uncaughtException(Thread t,Throwable e){AppLog.write("UNCAUGHT on "+t.getName()+": "+stack(e));android.os.Process.killProcess(android.os.Process.myPid());System.exit(10);}});setContentView(R.layout.activity_main);status=(TextView)findViewById(R.id.status);log=(TextView)findViewById(R.id.log);logScroll=(ScrollView)findViewById(R.id.logScroll);surface=(SurfaceView)findViewById(R.id.guestSurface);surface.getHolder().addCallback(this);
  filesButton=(Button)findViewById(R.id.filesButton); startButton=(Button)findViewById(R.id.startButton);
  filesButton.setOnClickListener(new View.OnClickListener(){public void onClick(View v){pick();}});((Button)findViewById(R.id.inspectButton)).setOnClickListener(new View.OnClickListener(){public void onClick(View v){append(GuestPackageManager.inspect(MainActivity.this));}});startButton.setOnClickListener(new View.OnClickListener(){public void onClick(View v){start();}});((Button)findViewById(R.id.stopButton)).setOnClickListener(new View.OnClickListener(){public void onClick(View v){stop();}});((Button)findViewById(R.id.exportLogButton)).setOnClickListener(new View.OnClickListener(){public void onClick(View v){exportLog();}});((Button)findViewById(R.id.clearLogButton)).setOnClickListener(new View.OnClickListener(){public void onClick(View v){clearLog();}});
  log.setText(AppLog.read());append("Stage 68 slot suffix fstab fix enabled");append(GuestPackageManager.inspect(this)); updateControls(); }
 private void downloadGuest(){if(guestBusy)return; setGuestBusy(true,"downloading AOSP ARM64 guest");append("Download started: "+GuestDownloader.NAME);new Thread(new Runnable(){public void run(){try{GuestDownloader.download(MainActivity.this,new GuestDownloader.Progress(){public void onMessage(final String s){runOnUiThread(new Runnable(){public void run(){append(s);}});}});runOnUiThread(new Runnable(){public void run(){status.setText("Status: guest downloaded");append(GuestPackageManager.inspect(MainActivity.this));setGuestBusy(false,null);}});}catch(final Throwable e){AppLog.write("DOWNLOAD ERROR: "+stack(e));runOnUiThread(new Runnable(){public void run(){status.setText("Status: download failed");append("Error: "+e.toString());setGuestBusy(false,null);}});}}}).start();}
 private void pick(){if(guestBusy)return; Intent i=new Intent(Intent.ACTION_OPEN_DOCUMENT);i.addCategory(Intent.CATEGORY_OPENABLE);i.setType("application/zip");i.addFlags(Intent.FLAG_GRANT_READ_URI_PERMISSION);startActivityForResult(i,PICK_ZIP);}
 @Override protected void onActivityResult(int r,int c,Intent d){super.onActivityResult(r,c,d);if(r==PICK_ZIP&&c==RESULT_OK&&d!=null)importZip(d.getData()); if(r==PICK_ENGINE&&c==RESULT_OK&&d!=null)importEngine(d.getData());}

 private void pickEngine(){Intent i=new Intent(Intent.ACTION_OPEN_DOCUMENT);i.addCategory(Intent.CATEGORY_OPENABLE);i.setType("application/zip");i.addFlags(Intent.FLAG_GRANT_READ_URI_PERMISSION);startActivityForResult(i,PICK_ENGINE);}
 private void importEngine(final Uri u){append("QEMU engine ZIP import started");new Thread(new Runnable(){public void run(){try{EngineImporter.importZip(MainActivity.this,u,new EngineImporter.Progress(){public void onMessage(final String s){runOnUiThread(new Runnable(){public void run(){append(s);}});}});runOnUiThread(new Runnable(){public void run(){append(QemuEngine.engineReport(MainActivity.this));status.setText("Status: engine imported");}});}catch(final Throwable e){runOnUiThread(new Runnable(){public void run(){append("ENGINE IMPORT ERROR: "+e.toString());status.setText("Status: engine import failed");}});}}}).start();}
 private void importZip(final Uri u){if(guestBusy)return; setGuestBusy(true,"importing guest ZIP");append("Manual ZIP import started");new Thread(new Runnable(){public void run(){try{GuestPackageManager.importZip(MainActivity.this,u,new GuestPackageManager.Progress(){public void onMessage(final String s){runOnUiThread(new Runnable(){public void run(){append(s);}});}});runOnUiThread(new Runnable(){public void run(){status.setText("Status: guest prepared");append(GuestPackageManager.inspect(MainActivity.this));setGuestBusy(false,null);}});}catch(final Throwable e){AppLog.write("IMPORT ERROR: "+stack(e));runOnUiThread(new Runnable(){public void run(){status.setText("Status: import failed");append("Error: "+e.toString());setGuestBusy(false,null);}});}}}).start();}
 private void start(){append("START pressed");if(guestBusy){append("START ABORT: guest import/download is still running");return;}try{append("Stage 68 start");append("Checking guest files...");if(!GuestPackageManager.bootReady(this)){status.setText("Status: guest incomplete");append("START ABORT: guest incomplete");return;}append("Guest files complete and size-verified");append("Surface ready = "+ready);if(GuestPackageManager.isCuttlefish(this)){append("CUTTLEFISH IMAGE DETECTED");append(GuestPackageManager.inspect(this));append(QemuEngine.engineReport(this));if(!QemuEngine.isPresent(this)){status.setText("Status: QEMU engine required");append("BOOT NOT ATTEMPTED: QEMU engine missing");return;}status.setText("Status: Cuttlefish Stage 68 boot");new Thread(new Runnable(){public void run(){try{VmKeepAliveService.begin(MainActivity.this);QemuEngine.nativeLibraryPreflightCuttlefish(MainActivity.this,new QemuEngine.Logger(){public void log(final String m){runOnUiThread(new Runnable(){public void run(){append(m);}});}});QemuEngine.selfTest(MainActivity.this,new QemuEngine.Logger(){public void log(final String m){runOnUiThread(new Runnable(){public void run(){append(m);}});}});QemuEngine.launchCuttlefishProbe(MainActivity.this,new QemuEngine.Logger(){public void log(final String m){runOnUiThread(new Runnable(){public void run(){append(m);}});}});VmKeepAliveService.end(MainActivity.this);}catch(final Throwable x){VmKeepAliveService.end(MainActivity.this);runOnUiThread(new Runnable(){public void run(){append("CUTTLEFISH BOOT ERROR: "+x.toString());append(stack(x));status.setText("Status: Cuttlefish failed");}});}}}).start();return;}append(QemuEngine.engineReport(this));append("Prepared command: "+QemuEngine.commandForLog(this));if(!QemuEngine.isPresent(this)){status.setText("Status: QEMU engine required");append("BOOT NOT ATTEMPTED: Android/Bionic ARM64 QEMU engine is not present.");append("Use Engine to import a QEMU bundle ZIP, or package a genuine engine in jniLibs for executable use.");return;}status.setText("Status: QEMU self-test");new Thread(new Runnable(){public void run(){try{QemuEngine.nativeLibraryPreflight(MainActivity.this,new QemuEngine.Logger(){public void log(final String m){runOnUiThread(new Runnable(){public void run(){append(m);}});}});QemuEngine.selfTest(MainActivity.this,new QemuEngine.Logger(){public void log(final String m){runOnUiThread(new Runnable(){public void run(){append(m);}});}});runOnUiThread(new Runnable(){public void run(){append("QEMU self-test PASSED; starting guest...");status.setText("Status: QEMU starting");}});QemuEngine.launch(MainActivity.this,new QemuEngine.Logger(){public void log(final String m){runOnUiThread(new Runnable(){public void run(){append(m);}});}});}catch(final Throwable x){runOnUiThread(new Runnable(){public void run(){append("QEMU ERROR: "+x.toString());append(stack(x));status.setText("Status: QEMU failed");}});}}}).start();}catch(Throwable e){append("START EXCEPTION: "+e.toString());append(stack(e));}}

 private void setGuestBusy(boolean b,String action){guestBusy=b;if(action!=null)status.setText("Status: "+action);updateControls();append(b?"Guest preparation lock ON - START disabled":"Guest preparation lock OFF");}
 private void updateControls(){if(startButton!=null)startButton.setEnabled(!guestBusy);if(filesButton!=null)filesButton.setEnabled(!guestBusy);}
 private void stop(){append("STOP pressed");append("STOP requested. Stage 8 launch shell does not yet keep a Process handle for termination.");status.setText("Status: stopped");}
 private void exportLog(){try{String p=DownloadExporter.copyLog(this,AppLog.getFile());append("Log exported: "+p);}catch(Throwable e){append("Log export failed: "+e.toString());}}
 private void clearLog(){if(AppLog.clear()){if(log!=null)log.setText("");status.setText("Status: log cleared");}else{Toast.makeText(this,"Could not clear log",Toast.LENGTH_SHORT).show();}}
 private void append(String s){AppLog.write(s);if(log!=null){log.append(s+"\n");if(logScroll!=null)logScroll.post(new Runnable(){public void run(){logScroll.fullScroll(View.FOCUS_DOWN);}});}}
 private static String stack(Throwable e){StringWriter sw=new StringWriter();PrintWriter pw=new PrintWriter(sw);e.printStackTrace(pw);pw.flush();return sw.toString();}
 @Override public void surfaceCreated(SurfaceHolder h){ready=true;append("Surface created");} @Override public void surfaceChanged(SurfaceHolder h,int f,int w,int he){AppLog.write("Surface changed "+w+"x"+he);} @Override public void surfaceDestroyed(SurfaceHolder h){ready=false;AppLog.write("Surface destroyed");}

 @Override protected void onPause(){AppLog.write("LIFECYCLE onPause");super.onPause();}
 @Override protected void onStop(){AppLog.write("LIFECYCLE onStop (app no longer visible)");super.onStop();}
 @Override protected void onDestroy(){AppLog.write("LIFECYCLE onDestroy finishing="+isFinishing());super.onDestroy();}
 @Override public void onTrimMemory(int level){AppLog.write("LIFECYCLE onTrimMemory level="+level);super.onTrimMemory(level);}
 @Override public void onLowMemory(){AppLog.write("LIFECYCLE onLowMemory");super.onLowMemory();}
}
